// tunit_dsw.sv - the DIP switches the board reads, from the OSD options of the System Options page
// Generated by tools/tunit_dips.py --gen; do not edit.
//
// Each option's value 0 is MAME's default, so all-zero status bits are the default switches.
// Bits no option has keep MAME's default. The word is the board's 16-bit DIP input (bit 0 is
// the Test Switch, active low).
//
// Copyright (C) 2026 Gm0rk - GPL-3.0-or-later

module tunit_dsw (
	input  [2:0]   game_id,
	input  [127:0] status,
	output reg [15:0] dsw
);

// Coinage (JD): 3, 1, 2, 4, ECA, Free Play
reg [2:0] jd_coinage;
always @(*) begin
	case (status[56:54])
		3'd0: jd_coinage = 3'd5;
		3'd1: jd_coinage = 3'd7;
		3'd2: jd_coinage = 3'd3;
		3'd3: jd_coinage = 3'd1;
		3'd4: jd_coinage = 3'd6;
		3'd5: jd_coinage = 3'd0;
		default: jd_coinage = 3'd5;
	endcase
end

// Counters (JD): One 1/1, One Totalizing, Two 1/1
reg [1:0] jd_counters;
always @(*) begin
	case (status[87:86])
		2'd0: jd_counters = 2'd0;
		2'd1: jd_counters = 2'd2;
		2'd2: jd_counters = 2'd1;
		default: jd_counters = 2'd0;
	endcase
end

// Country (JD): USA, French, German
reg [1:0] jd_country;
always @(*) begin
	case (status[89:88])
		2'd0: jd_country = 2'd3;
		2'd1: jd_country = 2'd2;
		2'd2: jd_country = 2'd1;
		default: jd_country = 2'd3;
	endcase
end

// Coinage (MK2): USA-1, USA-2, USA-3, USA-4, USA-ECA, USA-Free Play, German-1, German-2, German-3, German-4, German-5, German-ECA, German-Free Play, French-1, French-2, French-3, French-4, French-ECA, French-Free Play
reg [4:0] mk2_coinage;
always @(*) begin
	case (status[58:54])
		5'd0: mk2_coinage = 5'd31;
		5'd1: mk2_coinage = 5'd15;
		5'd2: mk2_coinage = 5'd23;
		5'd3: mk2_coinage = 5'd7;
		5'd4: mk2_coinage = 5'd27;
		5'd5: mk2_coinage = 5'd3;
		5'd6: mk2_coinage = 5'd29;
		5'd7: mk2_coinage = 5'd13;
		5'd8: mk2_coinage = 5'd21;
		5'd9: mk2_coinage = 5'd5;
		5'd10: mk2_coinage = 5'd25;
		5'd11: mk2_coinage = 5'd9;
		5'd12: mk2_coinage = 5'd1;
		5'd13: mk2_coinage = 5'd30;
		5'd14: mk2_coinage = 5'd14;
		5'd15: mk2_coinage = 5'd22;
		5'd16: mk2_coinage = 5'd6;
		5'd17: mk2_coinage = 5'd26;
		5'd18: mk2_coinage = 5'd2;
		default: mk2_coinage = 5'd31;
	endcase
end

// Coinage (MK): USA-1, USA-2, USA-3, USA-4, USA-ECA, USA-Free Play, German-1, German-2, German-3, German-4, German-5, German-ECA, German-Free Play, French-1, French-2, French-3, French-4, French-ECA, French-Free Play
reg [4:0] mk_coinage;
always @(*) begin
	case (status[58:54])
		5'd0: mk_coinage = 5'd31;
		5'd1: mk_coinage = 5'd15;
		5'd2: mk_coinage = 5'd23;
		5'd3: mk_coinage = 5'd7;
		5'd4: mk_coinage = 5'd27;
		5'd5: mk_coinage = 5'd3;
		5'd6: mk_coinage = 5'd29;
		5'd7: mk_coinage = 5'd13;
		5'd8: mk_coinage = 5'd21;
		5'd9: mk_coinage = 5'd5;
		5'd10: mk_coinage = 5'd25;
		5'd11: mk_coinage = 5'd9;
		5'd12: mk_coinage = 5'd1;
		5'd13: mk_coinage = 5'd30;
		5'd14: mk_coinage = 5'd14;
		5'd15: mk_coinage = 5'd22;
		5'd16: mk_coinage = 5'd6;
		5'd17: mk_coinage = 5'd26;
		5'd18: mk_coinage = 5'd2;
		default: mk_coinage = 5'd31;
	endcase
end

// Coinage (NBA): 1, 2, 3, 4, ECA, Free Play
reg [2:0] nba_coinage;
always @(*) begin
	case (status[56:54])
		3'd0: nba_coinage = 3'd7;
		3'd1: nba_coinage = 3'd3;
		3'd2: nba_coinage = 3'd5;
		3'd3: nba_coinage = 3'd1;
		3'd4: nba_coinage = 3'd6;
		3'd5: nba_coinage = 3'd0;
		default: nba_coinage = 3'd7;
	endcase
end

// Counters (NBA): One 1/1, One Totalizing, Two 1/1
reg [1:0] nba_counters;
always @(*) begin
	case (status[87:86])
		2'd0: nba_counters = 2'd3;
		2'd1: nba_counters = 2'd2;
		2'd2: nba_counters = 2'd1;
		default: nba_counters = 2'd3;
	endcase
end

// Country (NBA): USA, French, German
reg [1:0] nba_country;
always @(*) begin
	case (status[89:88])
		2'd0: nba_country = 2'd3;
		2'd1: nba_country = 2'd2;
		2'd2: nba_country = 2'd1;
		default: nba_country = 2'd3;
	endcase
end

wire [15:0] dsw_mk = {~status[64], ~status[62], ~status[63], ~status[61], ~status[65], 1'b1, 1'b1, status[68], status[60], mk_coinage, status[66], ~status[59]};
wire [15:0] dsw_mk2 = {~status[64], ~status[62], ~status[63], ~status[61], ~status[65], ~status[67], status[69], status[68], status[60], mk2_coinage, status[66], ~status[59]};
wire [15:0] dsw_nba = {status[60], nba_coinage, nba_country, nba_counters, ~status[70], ~status[67], ~status[71], 1'b1, 1'b1, 1'b1, status[69], ~status[59]};
wire [15:0] dsw_jd = {status[60], jd_coinage, jd_country, jd_counters, ~status[72], ~status[67], ~status[62], 1'b1, 1'b1, 1'b1, 1'b1, ~status[59]};

always @(*) begin
	case (game_id)
		3'd0, 3'd1: dsw = dsw_mk;       // Mortal Kombat (Plus too)
		3'd2:       dsw = dsw_mk2;      // Mortal Kombat II (Plus and rev 4.0 too)
		3'd3, 3'd4: dsw = dsw_nba;      // NBA Jam, NBA Jam Tournament Edition
		default:    dsw = dsw_jd;       // Judge Dredd
	endcase
end

endmodule
